# apply MVNW_REPOURL and calculate MAVEN_HOME
# maven home pattern: ~/.m2/wrapper/dists/{apache-maven-<version>,maven-mvnd-<version>-<platform>}/<hash>
if ($env:MVNW_REPOURL) {
  $MVNW_REPO_PATTERN = if ($USE_MVND -eq $False) { "/org/apache/maven/" } else { "/maven/mvnd/" }
  $distributionUrl = "$env:MVNW_REPOURL$MVNW_REPO_PATTERN$($distributionUrl -replace "^.*$MVNW_REPO_PATTERN",'')"
}
$distributionUrlName = $distributionUrl -replace '^.*/',''
$distributionUrlNameMain = $distributionUrlName -replace '\.[^.]*$','' -replace '-bin$',''

$MAVEN_M2_PATH = "$HOME/.m2"
if ($env:MAVEN_USER_HOME) {
  $MAVEN_M2_PATH = "$env:MAVEN_USER_HOME"
}

if (-not (Test-Path -Path $MAVEN_M2_PATH)) {
    New-Item -Path $MAVEN_M2_PATH -ItemType Directory | Out-Null
}

$MAVEN_WRAPPER_DISTS = $null
if ((Get-Item $MAVEN_M2_PATH).Target[0] -eq $null) {
  $MAVEN_WRAPPER_DISTS = "$MAVEN_M2_PATH/wrapper/dists"
} else {
  $MAVEN_WRAPPER_DISTS = (Get-Item $MAVEN_M2_PATH).Target[0] + "/wrapper/dists"
}

$MAVEN_HOME_PARENT = "$MAVEN_WRAPPER_DISTS/$distributionUrlNameMain"
$MAVEN_HOME_NAME = ([System.Security.Cryptography.SHA256]::Create().ComputeHash([byte[]][char[]]$distributionUrl) | ForEach-Object {$_.ToString("x2")}) -join ''
$MAVEN_HOME = "$MAVEN_HOME_PARENT/$MAVEN_HOME_NAME"

if (Test-Path -Path "$MAVEN_HOME" -PathType Container) {
  Write-Verbose "found existing MAVEN_HOME at $MAVEN_HOME"
    }

    /** 已解析操作的执行核心：快照 → apply → 撤销记录（均由模型负责）→ 动画/瞬时重建 → 父组变化重解析 */
    private boolean performResolvedDrop(Object dragged, DropResolver.Operation op,
                                        double gapTopY, PreviewListCell cell) {
        // 快照、受影响条目、各自操作前的父组指针、合并载荷与撤销记录的压栈全在模型内完成 ——
        // 采集顺序必须早于数据序修改，那个约束现在由 WorkspaceModel.applyResolvedDrop 独占保证。
        WorkspaceModel.DropResult drop = host.applyResolvedDrop(op);
        // 注意：DropResolver 拖拽致空组（R4）在原实现与新实现下都**只改结构、不打日志**；
        // log.workspacemodel.01 只属于 WorkspaceModel.group(...) 与 removeItems(...) 两条路径，本步未触碰。
        // 合并语义的打点（log.maincontroller.42）文案、实参、调用次数与位置一律保持原样。
        if (drop.changed() && drop.type() == UndoManager.RecordType.MERGE_GROUPS) {
            log.info(Texts.msg("log.maincontroller.42", drop.merged().getName(),
                    drop.mergeTarget().getName(), drop.mergedMembers().size(), drop.merged().getName()));
        }
        if (cell != null) {
            animateReleaseInsert(dragged, gapTopY);
        } else {
            // 空白吸附：瞬时重建显示序并复位拖拽状态
            host.rebuildDisplay();
            finishDragReset();
        }
        // 项目入组/出组/组合并 → 生效参数切换：受影响项目清缓存重新预解析（阶段 5 机制）
        List<PreviewItem> reparse = new ArrayList<>();
        for (PreviewItem it : drop.affected()) {
            if (!it.removed && drop.affectedBefore().get(it) != it.parentGroup) {
                // 条目独立参数生命周期拍板：入组即清除条目级参数（组内成员只认组参数）
                if (it.parentGroup != null) {
                    it.textItemParams = null;
                    it.imageItemParams = null;
                }
                host.clearPreviewCache(it);
                reparse.add(it);
            }
        }
        if (!reparse.isEmpty() && host.isCurrentModeConfirmed()) {
            host.startPreParseFor(reparse);
        }
        return true;
    }

    // ==================== 拖拽排序动画 ====================

    PreviewListCell findCell(Object item) {
        for (javafx.scene.Node n : host.fileListView().lookupAll(".list-cell")) {
            if (n instanceof PreviewListCell c && c.getItem() == item) {
                return c;
            }
        }
        return null;
    }

    /** 提起：被拖条目从显示序瞬间移除（数据序不动），下方条目快照上滑 0.2s 补位 */
    @Override
    public void beginDrag(PreviewListCell sourceCell) {
        draggedObject = sourceCell.getItem();
        dragPositionStale = false;
        dragActive = true;
        double dragGapTopY = DragGeometry.cellBoundsInOverlay(sourceCell, host.dragOverlay()).getMinY();
        double rowHeight = sourceCell.getHeight();

        List<PreviewListCell> cells = new ArrayList<>();
        List<ImageView> views = new ArrayList<>();
        try {
            for (javafx.scene.Node n : host.fileListView().lookupAll(".list-cell")) {
                if (n instanceof PreviewListCell c && c != sourceCell && c.getItem() != null
                        && !(c.getItem() instanceof PreviewItem it && it.removed)) {
                    Bounds b = DragGeometry.cellBoundsInOverlay(c, host.dragOverlay());
                    if (b.getMinY() >= dragGapTopY - 1) {
                        cells.add(c);
                        ImageView iv = new ImageView(c.snapshot(DragGeometry.transparentSnapParams(), null));
                        iv.setLayoutX(b.getMinX());
                        iv.setLayoutY(b.getMinY());
                        host.dragOverlay().getChildren().add(iv);
                        views.add(iv);
                    }
                }
            }
        } catch (Exception ex) {
            // 快照失败兜底：瞬时重排复位（cancelDrag 会清除 dragActive，防卡死）
     * 批量勾选写入（F1）—— 「勾选」这一提取输入事实的<b>唯一写入口</b>（B3-1）：
     * 逐条写 {@link PreviewItem#setSelected}（仅在值确实变化时通知监听器，与既有语义一致）。
     *
     * <p><b>静默写入</b>：不发布 {@link WorkspaceChange}（勾选不改变数据序/分组结构；
     * 发布会让订阅方做全量投影重建，破坏「勾选不触发滚动/焦点」的既有语义）；
     * 本类也不触碰任何 UI 选中/焦点状态。三态推导（{@code TriState}）仍由读取方
     * （端口 {@code workspace().selection()} / GUI 的 {@code SelectionRules}）按当前
     * {@code selected} 事实导出。</p>
     */
    public void setChecked(List<PreviewItem> targets, boolean value) {
        for (PreviewItem t : distinctNonNull(targets)) {
            t.setSelected(value);
        }
    }

    /**
     * 组改名（B3-2）：新名按<b>模型组名集合</b>（排除自身）唯一化后写入 —— 组名唯一化的唯一来源
     * 是 {@link #groupNames()} 所代表的顶层组集合，调用方不再自行收集其它组名；
     * 成功后该组<b>永久退出</b>「未命名组」提醒（{@code defaultNamed=false}，与 GUI 提交改名的既有语义一致）。
     *
     * <p><b>不发布变更</b>：组名不改变数据序/结构；改名后的列表刷新走
     * {@link GroupItem#addNameChangeListener} 的既有通知（值确实变化才触发）。</p>
     *
     * @param newName 期望的新名（null / 空白名原样透传，与 {@code GroupStructure.uniqueGroupName} 一致）
     * @return 实际生效的组名（唯一化之后）；组不在顶层时返回 {@code null} 且不产生任何变更
     */
    public String renameGroup(long groupNo, String newName) {
        GroupItem<PreviewItem> g = groupByNo(groupNo);
        if (g == null) {
            return null;
        }
        Set<String> others = new LinkedHashSet<>();
        for (Object o : topLevel) {
            if (o instanceof GroupItem<?> og && og != g) {
                others.add(og.getName());
            }
        }
        String unique = GroupStructure.uniqueGroupName(newName, others);
        g.setName(unique);
        g.setDefaultNamed(false);
        return unique;
    }

    /**
     * 折叠/展开翻转（B3-2）—— 「展开状态」的<b>唯一写入口</b>：每调用恰好翻转一次
     * {@link GroupItem#isExpanded()}。幂等语义 = 翻转由后端按<b>当前状态</b>原子完成，
     * 调用方不传目标值 —— 快速连续调用（双击连点）是「翻过去再翻回来」，
     * 不会基于陈旧读数把同一个目标值应用两次。
     *
     * <p><b>不发布变更</b>：展开/折叠不改变数据序本身；显示序投影（展开成员进/出
     * {@link #displayOrder()}）由调用方显式重建（GUI 的抽屉动画在动画起始帧重建）。</p>
     *
     * @return true = 确实翻转；false = 组不在顶层（no-op）
     */
    public boolean toggleGroupExpanded(long groupNo) {
        GroupItem<PreviewItem> g = groupByNo(groupNo);
        if (g == null) {
            return false;
        }
        g.setExpanded(!g.isExpanded());
        return true;
    }

    /**
     * 按组号拆分组（B3-2）：{@link #ungroup(GroupItem)} 的组号寻址重载（端口命令
     * {@code ungroup(long)} 的底座）；组不在顶层时为 no-op（返回空列表且不产生任何变更）。
     */
    public List<PreviewItem> ungroup(long groupNo) {
        GroupItem<PreviewItem> g = groupByNo(groupNo);
        return g == null ? List.of() : ungroup(g);
    }

    // ==================== 变更：拖拽落点（REORDER / MERGE_GROUPS） ====================

    /**
     * （GUI）决定怎么记日志、怎么清缓存、怎么重解析。</p>
     *
     * <p><b>字段顺序即调用顺序</b>：{@code affectedBefore} 的父组指针必须在
     * {@code DropResolver.apply} <b>之前</b>采集，故由本记录一并带出，调用方不得自行重采。</p>
     *
     * <p><b>不含"哪些组被拖拽致空销毁"</b>：那是 {@code DropResolver} 内部（R4）的结构效果，
     * 且原实现与新实现下都<b>不打日志</b>；本记录若再回传一份，就成了对同一语义的第二处（事后反推的）
     * 实现 —— 违反"同一语义全仓库只有一个实现点"。</p>
     *
     * @param changed        数据序是否真的发生了结构变化（原位 no-op 为 false，此时<b>不</b>压撤销记录）
     * @param affected       拖拽中父组可能变化的条目（原 {@code MainController.parentChangeTargets(op)} 的语义）
     * @param type           {@link UndoManager.RecordType#REORDER} 或 {@link UndoManager.RecordType#MERGE_GROUPS}
     * @param affectedBefore 与 {@code affected} 逐一对应的<b>操作前</b>父组指针（同一份 IdentityHashMap 语义）
     * @param merged        合并语义下被拖（销毁）的组；非合并为 {@code null}
     * @param mergedMembers 合并语义下被拖组的成员副本（操作前的组内顺序）；非合并为空列表
     * @param mergedIndex   合并语义下被拖组操作前的顶层索引；非合并为 -1
     * @param mergeTarget   合并语义下的目标组；非合并为 {@code null}（仅用于调用方产
     *                      {@code log.maincontroller.42} 的本地化文案）
     */
    public record DropResult(boolean changed,
                             List<PreviewItem> affected,
                             UndoManager.RecordType type,
                             Map<PreviewItem, GroupItem<PreviewItem>> affectedBefore,
                             GroupItem<PreviewItem> merged,
                             List<PreviewItem> mergedMembers,
                             int mergedIndex,
                             GroupItem<PreviewItem> mergeTarget) {
    }

    /**
     * 执行一次**已解析**的拖放操作（{@link DropResolver.Operation}）：整包收进模型，
     * 内部完成"快照 → 应用 → 重建父组指针 → 压撤销记录"。
     *
     * <p><b>为什么必须收进来</b>：{@code DropResolver.apply(topLevel, ...)} 是**间接写** ——
     * 它与 GUI 的直写一样绕过模型的撤销记录与结构维护，不报错、只静默分叉。
     * 本方法把"共享数据序的唯一写入者"这一性质补全到拖拽路径
     * （{@code ArchitectureTest.guiDoesNotMutateDataOrderDirectly} 的间接写处数因此归零）。</p>
     *
     * <p><b>采集顺序即语义（本方法最容易写错的地方）</b>：结构快照、受影响条目、各条目<b>操作前</b>的
     * 父组指针、以及合并载荷（被拖组 / 其顶层索引 / 其成员副本）—— 五者都必须在
     * {@link DropResolver#apply} <b>之前</b>采集。顺序错了不会报错，只会把<b>操作后</b>的状态
     * 记成"操作前"，使撤销一步之后回到错误的结构。</p>
     *
     * <p><b>落点解析不在本类</b>：{@link DropResolver#resolve} 依赖"目标行在显示序中的位置"等
     * GUI 概念，仍留在调用方；本类只负责"把已解析的操作落到数据序上"。
     * {@link DropResolver#apply} 的签名与语义<b>不变</b>（{@code DropResolverTest} 的 35 条断言依赖它）。</p>
     *
     * @param op 已解析的落点操作（{@code null} 时返回"未变更"的空结果，不触碰任何状态）
     * @return 结构结果；{@code changed == false} 时数据序与撤销栈均未被改动
     */
    @SuppressWarnings("unchecked")
    public DropResult applyResolvedDrop(DropResolver.Operation op) {
        if (op == null) {
            return new DropResult(false, List.of(), UndoManager.RecordType.REORDER,
                    Map.of(), null, List.of(), -1, null);
        }
        // ① 快照与合并载荷须在数据序修改前采集
        List<Object> before = GroupStructure.snapshotStructure(topLevel);
        List<PreviewItem> affected = collectAffected(op);
        Map<PreviewItem, GroupItem<PreviewItem>> prevParents = new IdentityHashMap<>();
        for (PreviewItem it : affected) {
            prevParents.put(it, it.parentGroup);
        }
        boolean merge = op instanceof DropResolver.MergeInto;
        UndoManager.RecordType type = merge
                ? UndoManager.RecordType.MERGE_GROUPS : UndoManager.RecordType.REORDER;
        GroupItem<PreviewItem> merged = null;
        GroupItem<PreviewItem> mergeTarget = null;
        int mergedIdx = -1;
        List<PreviewItem> mergedMembers = List.of();
        if (merge) {
            merged = (GroupItem<PreviewItem>) ((DropResolver.MergeInto) op).dragged();
            mergeTarget = (GroupItem<PreviewItem>) ((DropResolver.MergeInto) op).target();
            mergedIdx = topLevel.indexOf(merged);
            mergedMembers = new ArrayList<>(merged.getMembers());
        }
        // ② 落点生效
        boolean changed = DropResolver.apply(topLevel, op, REMOVED);
        // ③ 父组指针以数据序为准统一重建（撤销恢复也走这里，不留第二份实现）
        rebuildParentPointers();
        // ④ 一次拖放会话 = 一条撤销记录（载荷与迁移前逐字段一致）
        //    ⚠️ 拖拽致空组（R4）的销毁由 DropResolver.apply 内部完成，且在原实现与新实现下都是
        //    **静默**的（只改结构、不打日志）—— 因此本方法不回传"哪些组被销毁"，调用方也无日志可打。
        //    log.workspacemodel.01 只属于 group(...) / removeItems(...) 两条路径，本步未触碰。
        if (changed) {
            if (merge) {
                undoManager.push(new UndoManager.Record<>(type, mergedMembers, merged,
                        mergedIdx, List.of(), List.of(), before));
            } else {
                undoManager.push(new UndoManager.Record<>(type,
                        op instanceof DropResolver.InsertTop it && it.item() instanceof PreviewItem p
                                ? List.of(p)
                                : op instanceof DropResolver.InsertInto ii && ii.item() instanceof PreviewItem p2
                                        ? List.of(p2)
                                        : List.of(),
                        null, -1, List.of(), List.of(), before));
            }
            publish(merge ? WorkspaceChange.Kind.MERGED : WorkspaceChange.Kind.REORDERED, affected);
        }
        return new DropResult(changed, affected, type, prevParents,
                merged, mergedMembers, mergedIdx, mergeTarget);
    }

    /**
     * 拖拽中父组可能变化的条目（原 {@code MainController.parentChangeTargets} 语义，逐字迁移）：
     * 入组/出组的条目自身；组合并时为<b>被拖组的全部成员</b>（它们的生效参数随父组切换）。
     */
    private List<PreviewItem> collectAffected(DropResolver.Operation op) {
        if (op instanceof DropResolver.InsertTop it && it.item() instanceof PreviewItem p) {
            return List.of(p);
        }
        if (op instanceof DropResolver.InsertInto ii && ii.item() instanceof PreviewItem p) {
            return List.of(p);
        }
        if (op instanceof DropResolver.MergeInto mi && mi.dragged() instanceof GroupItem<?> g) {
            List<PreviewItem> out = new ArrayList<>();
            for (Object m : g.getMembers()) {
                if (m instanceof PreviewItem p) {
                    out.add(p);
                }
            }
            return out;
        }
        return List.of();
    }

