        try {
            opts = CliArgs.parse(args);
        } catch (CliArgs.UsageException e) {
            System.err.println("error: " + e.getMessage());
            System.err.println(usage());
            return EXIT_USAGE;
        }
        if (opts.help()) {
            System.out.println(usage());
            return EXIT_OK;
        }
